function rampartSimulate(createStrategy, seed, maxTicks, hooks) {
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  const GROUND_PTS = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const AIR_PTS = [[0,6],[21,6],[21,11],[23,11]];
  function buildRoute(pts) {
    const xs = [], ys = [];
    for (let i = 0; i + 1 < pts.length; i++) {
      const ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50;
      const bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      const len = Math.abs(bx - ax) + Math.abs(by - ay);
      const sx = Math.sign(bx - ax), sy = Math.sign(by - ay);
      for (let d = 0; d < len; d++) { xs.push(ax + sx * d); ys.push(ay + sy * d); }
    }
    const last = pts[pts.length - 1];
    xs.push(last[0] * 100 + 50); ys.push(last[1] * 100 + 50);
    return { xs, ys, len: xs.length - 1 };
  }
  const ROUTES = [buildRoute(GROUND_PTS), buildRoute(AIR_PTS)];
  const SLOT_TILES = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const TNAMES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  const TS = {
    bolt:   { idx: 0, cost: 50,  dmg: 26,  per: 8,  rng: 300, spl: 0,  slow: 0,  pierce: 0, ground: 1, air: 1 },
    cannon: { idx: 1, cost: 90,  dmg: 60,  per: 24, rng: 260, spl: 90, slow: 0,  pierce: 0, ground: 1, air: 0 },
    frost:  { idx: 2, cost: 70,  dmg: 10,  per: 12, rng: 240, spl: 0,  slow: 30, pierce: 0, ground: 1, air: 1 },
    lance:  { idx: 3, cost: 120, dmg: 180, per: 36, rng: 360, spl: 0,  slow: 0,  pierce: 1, ground: 1, air: 0 },
    flak:   { idx: 4, cost: 80,  dmg: 40,  per: 10, rng: 320, spl: 70, slow: 0,  pierce: 0, ground: 0, air: 1 }
  };
  const ENAMES = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  const ES = {
    grunt:     { hp: 60,  spd: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  spd: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  spd: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, spd: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  spd: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  spd: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,   spd: 12, bounty: 1, leak: 1, air: 0, first: 99, weight: 0 }
  };
  const rng = mulberry32(seed >>> 0);
  const mult = [0, 1000];
  function mOf(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  const comps = [null];
  function genWave(w) {
    const types = ENAMES.filter(n => ES[n].first <= w);
