          log.push([tick, 'B', sl, s.idx]); if (hooks && hooks.onBuild) hooks.onBuild(tick, sl, a.type, 1);
        } else if (a.op === 'upgrade') {
          const t = turrets[sl]; if (!t || t.tier >= 3) continue;
          const c = TS[t.type].cost * (t.tier === 1 ? 1 : 2);
          if (gold < c) continue;
          gold -= c; t.spent += c; t.tier++;
          log.push([tick, 'U', sl, t.tier]); if (hooks && hooks.onBuild) hooks.onBuild(tick, sl, t.type, t.tier);
        } else if (a.op === 'sell') {
          const t = turrets[sl]; if (!t) continue;
          gold += Math.floor(t.spent * 70 / 100); turrets[sl] = null;
          log.push([tick, 'S', sl, 0]); if (hooks && hooks.onSell) hooks.onSell(tick, sl, t.type, t.tier);
        }
      }
