const fs = require('fs');
const src = fs.readFileSync(__dirname + '/sim.js', 'utf8');
const sim = new Function(src + ';return rampartSimulate;')();
const TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
// genome strategy: steps = [{k:'b',s,t}|{k:'u',s}|{k:'x',s}]
const COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
function makeFactory(steps, opts) {
  opts = opts || {};
  return function createStrategy() {
    let ptr = 0;
    const tiers = new Array(16).fill(0), types = new Array(16).fill(null), spent = new Array(16).fill(0);
    return {
      plan(state) {
        let gold = state.gold; const acts = [];
        while (ptr < steps.length && acts.length < 32) {
          const st = steps[ptr];
          if (st.k === 'b') {
            if (tiers[st.s]) { ptr++; continue; }
            const c = COST[st.t]; if (gold < c) break;
            gold -= c; tiers[st.s] = 1; types[st.s] = st.t; spent[st.s] = c; acts.push({ op: 'build', slot: st.s, type: st.t }); ptr++;
          } else if (st.k === 'u') {
            if (!tiers[st.s] || tiers[st.s] >= 3) { ptr++; continue; }
            const c = COST[types[st.s]] * (tiers[st.s] === 1 ? 1 : 2); if (gold < c) break;
            gold -= c; spent[st.s] += c; tiers[st.s]++; acts.push({ op: 'upgrade', slot: st.s }); ptr++;
          } else {
            if (!tiers[st.s]) { ptr++; continue; }
            gold += Math.floor(spent[st.s] * 70 / 100); tiers[st.s] = 0; types[st.s] = null; spent[st.s] = 0;
            acts.push({ op: 'sell', slot: st.s }); ptr++;
          }
        }
        return acts;
      }
    };
  };
}
function evalSeeds(factory, seeds, maxTicks) {
  let tot = 0; const per = [];
  for (const sd of seeds) { const r = sim(factory, sd, maxTicks || 12020); tot += r.score; per.push(r.score); }
  return { mean: tot / seeds.length, per };
}
module.exports = { sim, makeFactory, evalSeeds, TYPES, COST };

