// =====================================================================
// Per-frame rendering: a pure function of simTime
// =====================================================================
const SLOW_TINT = new THREE.Color(0.55, 0.85, 1.7), NO_TINT = new THREE.Color(1, 1, 1);
const camRight = new THREE.Vector3(), camQ = new THREE.Quaternion();
const FALL_DEB = []; (function () { for (let i = 0; i < 70; i++) { const a = vrand() * Math.PI * 2, sp = 0.8 + vrand() * 3.4; FALL_DEB.push({ vx: Math.cos(a) * sp, vz: Math.sin(a) * sp, vy: 3 + vrand() * 5, s: 0.07 + vrand() * 0.17, rx: vrand() * 8, ry: vrand() * 8, c: vrand() }); } })();
const SLOT_DEFAULT_YAW = SLOT_TILES.map(function (s) {
  let best = 1e9, by = 0; const p = {};
  for (let d = 0; d <= ROUTES[0].len; d += 25) { routePos(0, d, p); const dx = p.x - (s[0] + 0.5), dz = p.z - (s[1] + 0.5), q = dx * dx + dz * dz; if (q < best) { best = q; by = Math.atan2(dx, dz); } }
  return by;
});
const WAVE_COL = ENEMY_COL;
const pp = { x: 0, z: 0, dx: 0, dz: 0 };
const ease = { back: function (x) { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2); } };

function renderScene(simTime) {
  const t = clamp(simTime, 0, DURATION);
  const fell = R.fallTick >= 0, tF = fell ? R.fallTick / TPS : 1e9;
  const tw = Math.min(t, tF);
  let k = Math.floor(tw * TPS), f = tw * TPS - k;
  if (k > MAXT) { k = MAXT; f = 0; }
  const tf = fell ? Math.max(0, t - tF) : 0;
  const D = S3;
  uTime.value = tw;
  uDesat.value = fell ? clamp(tf / 1.0, 0, 1) * 0.96 : 0;

  // camera + trauma shake
  const tr = traumaAt(t), amp = tr * tr * 0.25;
  camera.position.copy(camBasePos);
  camera.position.x += noise1(t * 16, 0) * amp; camera.position.z += noise1(t * 16 + 50, 1) * amp;
  camera.quaternion.copy(camBaseQuat);
  camera.updateMatrixWorld(true);
  camRight.set(1, 0, 0).applyQuaternion(camBaseQuat);
  camQ.copy(camBaseQuat);

  // ---------------- enemies ----------------
  const counts = {}; Object.keys(D.enemy).forEach(function (n) { counts[n] = 0; });
  D.pBar.begin(); D.pShadow.begin(); D.pDisc.begin(); D.pRing.begin(); D.pBeam.begin(); D.pSpark.begin(); D.pBox.begin();
  const ids = R.liveIds[k] || [];
  for (let n = 0; n < ids.length; n++) {
    const rec = R.ER[ids[n]];
    if (!rec) continue;
    if (rec.death >= 0 && k >= rec.death) continue;
    const p0 = progAt(rec, k); if (p0 < 0) continue;
    let p1 = progAt(rec, k + 1); if (p1 < 0) p1 = p0;
    const prog = p0 + (p1 - p0) * f;
    routePos(rec.air, prog, pp);
    let x = pp.x, z = pp.z, y = 0.0;
    const yaw = Math.atan2(pp.dx, pp.dz);
    let sc = 1;
    if (rec.deathKind === 'L') { const rem = ROUTES[rec.air].len - prog; if (rem < 70) sc = Math.max(0.2, rem / 70); }
    if (rec.splitIdx >= 0) {
      const ts = tw - rec.splitTick / TPS;
      if (ts >= 0 && ts < 0.5) { const u = Math.sin(Math.PI * ts / 0.5), a = rec.splitIdx * 2.094 + 0.6; x += Math.cos(a) * 0.42 * u; z += Math.sin(a) * 0.42 * u; y += 0.45 * u; }
    }
    const mesh = D.enemy[rec.type];
    if (rec.air) y = 0.8 + 0.05 * Math.sin(tw * 3.2 + rec.id); else y += 0.03 * Math.abs(Math.sin(tw * (rec.type === 'runner' ? 14 : 7) + rec.id));
