const fs = require('fs');
const { makeFactory, evalSeeds, TYPES } = require('./lib.js');
const rs = parseInt(process.argv[2] || '1'), iters = parseInt(process.argv[3] || '5000'), outFile = process.argv[4];
const nSeeds = parseInt(process.argv[5] || '32');
const initFile = process.argv[6];
const T0 = parseFloat(process.argv[7] || '0.2');
function mulberry(a) { return function () { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const R = mulberry(rs * 7919 + 13);
const ri = n => Math.floor(R() * n);
const seeds = []; for (let i = 1; i <= nSeeds; i++) seeds.push(1000 + i * 3);
const MODES = [0, 1, 2, 3, 4, 5, 7];
let init = JSON.parse(fs.readFileSync(initFile, 'utf8'));
if (Array.isArray(init)) init = { steps: init, tm: [2, 3, 0, 0, 3], mf: 0 };
let cur = init;
function score(g) { return evalSeeds(makeFactory(g.steps, { tm: g.tm, mf: g.mf }), seeds).mean; }
function randStep() {
  const r = R();
  if (r < 0.45) return { k: 'b', s: ri(16), t: TYPES[ri(5)] };
  if (r < 0.92) return { k: 'u', s: ri(16) };
  return { k: 'x', s: ri(16) };
}
function mutate(gn) {
  let g = gn.steps.map(x => Object.assign({}, x)); const tm = gn.tm.slice(); let mf = gn.mf;
  const n = 1 + (R() < 0.3 ? 1 : 0);
  for (let m = 0; m < n; m++) {
    const r = R();
    if (r < 0.06) { tm[ri(5)] = MODES[ri(MODES.length)]; }
    else if (r < 0.2) { const b = g.filter(x => x.k === 'b'); if (b.length) b[ri(b.length)].t = TYPES[ri(5)]; }
    else if (r < 0.35) { const i = ri(g.length), j = Math.min(g.length - 1, Math.max(0, i + ri(7) - 3)); const t = g[i]; g[i] = g[j]; g[j] = t; }
    else if (r < 0.5) { const i = ri(g.length); const [x] = g.splice(i, 1); g.splice(ri(g.length + 1), 0, x); }
    else if (r < 0.7) { g.splice(ri(g.length + 1), 0, randStep()); }
    else if (r < 0.8) { if (g.length > 5) g.splice(ri(g.length), 1); }
    else if (r < 0.9) { const x = g[ri(g.length)]; x.s = ri(16); }
    else { const i = ri(g.length); const x = g[i]; if (x.k === 'b') { x.s = ri(16); x.t = TYPES[ri(5)]; } }
  }
  if (g.length > 100) g.length = 100;
  return { steps: g, tm, mf };
}
let curS = score(cur), best = cur, bestS = curS;
console.log('start', curS);
for (let it = 0; it < iters; it++) {
  const T = T0 * Math.pow(0.015 / T0, it / iters);
  const cand = mutate(cur), s = score(cand);
  if (s >= curS || R() < Math.exp((s - curS) / T)) { cur = cand; curS = s; if (s > bestS) { best = cand; bestS = s; fs.writeFileSync(outFile, JSON.stringify(best)); } }
  if (it % 250 === 0) console.log(it, curS.toFixed(3), bestS.toFixed(3), 'len', cur.steps.length, JSON.stringify(cur.tm));
}
fs.writeFileSync(outFile, JSON.stringify(best));
console.log('done best', bestS);

