// =====================================================================
// Playback state machine, dock wiring, audio unlock, self-report
// =====================================================================
const $ = function (id) { return document.getElementById(id); };
const elCountdown = $('countdown'), elToggle = $('btn-toggle'), elRefire = $('btn-refire'), elScrub = $('scrubber');
const iconPause = $('icon-pause'), iconPlay = $('icon-play');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
let state = 'COUNTDOWN', simTime = 0, playbackSpeed = 1, countdownElapsed = 0, holdElapsed = 0, lastTs = null;

function showCountdown(txt) { elCountdown.style.display = 'block'; elCountdown.textContent = txt; }
function hideCountdown() { elCountdown.style.display = 'none'; elCountdown.textContent = ''; }
function setIcons(playing) {
  iconPause.style.display = playing ? '' : 'none';
  iconPlay.style.display = playing ? 'none' : '';
  elToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function draw() { if (GFX) { try { GFX.render(simTime); } catch (e) { if (!draw.warned) { draw.warned = true; console.error(e); } } } }

function frame(ts) {
  window.requestAnimationFrame(frame);
  const raw = lastTs === null ? 0 : (ts - lastTs) / 1000;
  lastTs = ts;
  const dt = Math.min(Math.max(raw, 0), 0.1);
  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) { hideCountdown(); state = 'PLAYING'; setIcons(true); }
    else showCountdown(countdownElapsed < 1 ? '3' : (countdownElapsed < 2 ? '2' : '1'));
  } else if (state === 'PLAYING') {
    const prev = simTime;
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    elScrub.value = simTime.toFixed(3);
    RampAudio.advance(prev, simTime);
    if (simTime >= DURATION) { simTime = DURATION; elScrub.value = DURATION.toFixed(3); state = 'ENDED'; setIcons(false); }
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) { state = 'PLAYING'; }
  }
  RampAudio.setActive(state === 'PLAYING');
  RampAudio.update(simTime, state === 'PLAYING');
  draw();
}

elToggle.addEventListener('click', function () {
  RampAudio.resume();
  if (state === 'PLAYING') { state = 'PAUSED'; setIcons(false); }
  else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') { hideCountdown(); simTime = 0; elScrub.value = '0'; state = 'PAUSED'; setIcons(false); draw(); }
  else if (state === 'PAUSED') { state = 'PLAYING'; setIcons(true); }
  else if (state === 'ENDED') { hideCountdown(); simTime = 0; elScrub.value = '0'; RampAudio.resetEvents(); state = 'PLAYING'; setIcons(true); draw(); }
});
elRefire.addEventListener('click', function () {
  RampAudio.resume(); RampAudio.resetEvents();
  hideCountdown(); simTime = 0; elScrub.value = '0'; countdownElapsed = 0; holdElapsed = 0;
  setIcons(true); state = 'REFIRE_HOLD'; draw();
});
elScrub.addEventListener('input', function () {
  hideCountdown();
  simTime = clamp(parseFloat(elScrub.value) || 0, 0, DURATION);
  state = 'PAUSED'; setIcons(false); draw();
});
pills.forEach(function (p) {
  p.addEventListener('click', function () {
    playbackSpeed = parseFloat(p.getAttribute('data-speed'));
    pills.forEach(function (q) { const on = q === p; q.classList.toggle('is-active', on); q.setAttribute('aria-checked', on ? 'true' : 'false'); });
  });
});
window.addEventListener('resize', function () { if (GFX) { try { GFX.resize(); } catch (e) {} } draw(); });
function unlock() { RampAudio.resume(); }
window.addEventListener('pointerdown', unlock); window.addEventListener('keydown', unlock);

// ---------------- self-check against the published vectors + machine-readable report ----------------
function selfCheck() {
  let a = false, b = false;
  try {
    const A = function () { return { plan: function (s) { const x = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { x.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return x; } }; };
    const ra = rampartSimulate(A, 42, 12020);
    a = ra.hash === '82a5353d' && ra.score === 25.38 && ra.fallTick === 1035 && ra.log.length === 166;
    const B = function () { return { plan: function (s) {
      if (s.wave === 1) return [{ op: 'build', slot: 3, type: 'cannon' }, { op: 'build', slot: 6, type: 'frost' }];
      if (s.wave === 3) return [{ op: 'upgrade', slot: 3 }, { op: 'build', slot: 12, type: 'flak' }];
      if (s.wave === 6) return [{ op: 'build', slot: 8, type: 'lance' }, { op: 'sell', slot: 6 }];
      return []; } }; };
    const rb = rampartSimulate(B, 7, 12020);
    b = rb.hash === '2e8858d7' && rb.score === 10.93 && rb.fallTick === 457 && rb.log.length === 48;
  } catch (e) {}
  return { vectorA: a, vectorB: b };
}
const STRAT_INFO = __STRATEGY_INFO__;
window.BENCH_REPORT = {
  selfCheck: selfCheck(),
  strategy: { summary: STRAT_INFO.summary, seedsTested: STRAT_INFO.seedsTested, meanScoreOnTestedSeeds: STRAT_INFO.mean },
  seed42: { score: R.res.score, fallTick: R.res.fallTick },
  systems: { board: GFX ? 'full' : 'missing', enemiesAndTurrets: GFX ? 'full' : 'missing', combatVisuals: GFX ? 'full' : 'missing', fall: GFX ? 'full' : 'missing', hud: GFX ? 'full' : 'missing', audio: 'full' },
  simplifications: STRAT_INFO.simplifications,
  testedInBrowser: __TESTED_IN_BROWSER__,
  measuredFps: null
};

// initial resting scene, then the countdown starts on the first animation frame
RampAudio.init();
showCountdown('3');
setIcons(true);
draw();
window.requestAnimationFrame(frame);

