function createStrategy() {
  // Build order found by offline search (simulated annealing over a purchase list scored on many
  // seeds), executed strictly in order each wave start with whatever gold is available.
  // Step: [op, slot, type]  op: 0 build, 1 upgrade, 2 sell
  var STEPS = __STEPS__;
  // Targeting mode per turret type (bolt, cannon, frost, lance, flak):
  // 0 default (closest to the base), 1 highest hp, 2 lowest hp, 3 densest cluster, 4 un-slowed first, 5 furthest back, 7 highest max hp
  var TM = __TM__;
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var ptr = 0;

  function plan(state) {
    var gold = state.gold, acts = [];
    var tier = [], type = [], spent = [], i;
    for (i = 0; i < 16; i++) {
      var t = state.slots[i].turret;
      tier.push(t ? t.tier : 0); type.push(t ? t.type : null); spent.push(t ? t.spent : 0);
    }
    while (ptr < STEPS.length && acts.length < 32) {
      var st = STEPS[ptr], s = st[1];
      if (st[0] === 0) {
        if (tier[s]) { ptr++; continue; }
        var c = COST[st[2]]; if (gold < c) break;
        gold -= c; tier[s] = 1; type[s] = st[2]; spent[s] = c; acts.push({ op: 'build', slot: s, type: st[2] }); ptr++;
      } else if (st[0] === 1) {
        if (!tier[s] || tier[s] >= 3) { ptr++; continue; }
        var uc = COST[type[s]] * (tier[s] === 1 ? 1 : 2); if (gold < uc) break;
        gold -= uc; spent[s] += uc; tier[s]++; acts.push({ op: 'upgrade', slot: s }); ptr++;
      } else {
        if (!tier[s]) { ptr++; continue; }
        gold += Math.floor(spent[s] * 70 / 100); tier[s] = 0; type[s] = null; spent[s] = 0; acts.push({ op: 'sell', slot: s }); ptr++;
      }
    }
    return acts;
  }

  function target(turret, cands) {
    var mode = TM[TYPES.indexOf(turret.type)], best = null, bs = -Infinity, i, j, c, d, n, sc;
    if (!mode) return -1;
    for (i = 0; i < cands.length; i++) {
      c = cands[i];
      if (mode === 1) sc = c.hp;
      else if (mode === 2) sc = -c.hp;
      else if (mode === 3) {
        n = 0;
        for (j = 0; j < cands.length; j++) { d = cands[j]; var dx = c.x - d.x, dy = c.y - d.y; if (dx * dx + dy * dy <= 8100) n++; }
        sc = n * 1e6 - c.remaining;
      }
      else if (mode === 4) sc = (c.slowed ? 0 : 1e6) - c.remaining;
      else if (mode === 5) sc = c.remaining;
      else if (mode === 7) sc = c.maxHp;
      else return -1;
      if (sc > bs) { bs = sc; best = c; }
    }
    return best ? best.id : -1;
  }
  return { plan: plan, target: target };
}

