const fs = require('fs');
const D = __dirname;
const rd = f => fs.readFileSync(D + '/' + f, 'utf8');
const genomeFile = process.argv[2], outFile = process.argv[3], tested = process.argv[4] === 'tested';
const infoFile = process.argv[5] || 'info.json';
let g = JSON.parse(rd(genomeFile));
if (Array.isArray(g)) g = { steps: g, tm: [0, 0, 0, 0, 0], mf: 0 };
const OPS = { b: 0, u: 1, x: 2 };
const steps = g.steps.map(s => s.k === 'b' ? '[0,' + s.s + ',"' + s.t + '"]' : '[' + OPS[s.k] + ',' + s.s + ']');
const lines = []; for (let i = 0; i < steps.length; i += 8) lines.push('    ' + steps.slice(i, i + 8).join(','));
let strat = rd('strat_tpl.js').replace('__STEPS__', '[\n' + lines.join(',\n') + '\n  ]').replace('__TM__', JSON.stringify(g.tm));
if (g.custom) strat = rd(g.custom).replace('__STEPS__', '[\n' + lines.join(',\n') + '\n  ]').replace('__TM__', JSON.stringify(g.tm));
const info = JSON.parse(rd(infoFile));
const gfx = rd('m2.js') + '\n' + rd('m3.js') + '\n' + rd('m4.js') + '\n' + rd('m6.js');
let main = rd('m1.js') + '\n' + rd('m5.js') + '\n' +
  'const GFX = hasTHREE ? (function () {\ntry {\n' + gfx + '\n} catch (e) { console.error(e); return null; }\n})() : null;\n' +
  rd('m7.js').replace('__STRATEGY_INFO__', JSON.stringify(info)).replace('__TESTED_IN_BROWSER__', tested ? 'true' : 'false');
let html = rd('template.html').replace('__STRATEGY__', () => strat.trim()).replace('__SIM__', () => rd('sim.js').trim()).replace('__MAIN__', () => main);
fs.writeFileSync(outFile, html);
fs.writeFileSync(D + '/strategy_out.js', strat);
console.log('wrote', outFile, html.length, 'bytes');

