// =====================================================================
// Per-frame rendering: a pure function of simTime
// =====================================================================
const SLOW_TINT = new THREE.Color(0.55, 0.85, 1.7), NO_TINT = new THREE.Color(1, 1, 1);
const camRight = new THREE.Vector3(), camQ = new THREE.Quaternion();
const FALL_DEB = []; (function () { for (let i = 0; i < 70; i++) { const a = vrand() * Math.PI * 2, sp = 0.8 + vrand() * 3.4; FALL_DEB.push({ vx: Math.cos(a) * sp, vz: Math.sin(a) * sp, vy: 3 + vrand() * 5, s: 0.07 + vrand() * 0.17, rx: vrand() * 8, ry: vrand() * 8, c: vrand() }); } })();
const SLOT_DEFAULT_YAW = SLOT_TILES.map(function (s) {
  let best = 1e9, by = 0; const p = {};
  for (let d = 0; d <= ROUTES[0].len; d += 25) { routePos(0, d, p); const dx = p.x - (s[0] + 0.5), dz = p.z - (s[1] + 0.5), q = dx * dx + dz * dz; if (q < best) { best = q; by = Math.atan2(dx, dz); } }
  return by;
});
const WAVE_COL = ENEMY_COL;
const pp = { x: 0, z: 0, dx: 0, dz: 0 };
const ease = { back: function (x) { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2); } };

