    let p1 = progAt(rec, k + 1); if (p1 < 0) p1 = p0;
    const prog = p0 + (p1 - p0) * f;
    routePos(rec.air, prog, pp);
    let x = pp.x, z = pp.z, y = 0.0;
    const yaw = Math.atan2(pp.dx, pp.dz);
    let sc = 1;
    if (rec.deathKind === 'L') { const rem = ROUTES[rec.air].len - prog; if (rem < 70) sc = Math.max(0.2, rem / 70); }
    if (rec.splitIdx >= 0) {
