      if (ts >= 0 && ts < 0.5) { const u = Math.sin(Math.PI * ts / 0.5), a = rec.splitIdx * 2.094 + 0.6; x += Math.cos(a) * 0.42 * u; z += Math.sin(a) * 0.42 * u; y += 0.45 * u; }
