    const h0 = hpAtRec(rec, k), h1 = hpAtRec(rec, Math.min(k + 1, rec.spawn + rec.hp.length - 1));
    const frac = clamp(lerp(h0, h1, f) / rec.maxHp, 0, 1), W = ENEMY_BAR_W[rec.type] * (rec.type === 'splitling' ? 1 : 1.0);
    const by = y + ENEMY_H[rec.type] * sc + (rec.air ? -0.1 : 0.16);
    D.pBar.add(x, by, z, camQ.x, camQ.y, camQ.z, camQ.w, W + 0.04, 0.095, 1, 0.02, 0.02, 0.03, 0.9);
