  }
  Object.keys(D.enemy).forEach(function (n) { const m = D.enemy[n]; m.count = Math.min(counts[n], 320); m.instanceMatrix.needsUpdate = true; m.instanceColor.needsUpdate = true; });

  // ---------------- turrets ----------------
  const tc = {}, pc = [0, 0, 0];
  TYPE_NAMES.forEach(function (n) { tc[n] = 0; });
  for (let s = 0; s < 16; s++) {
    const tu = turretAt(s, k); if (!tu) continue;
