const fs = require('fs');
const { sim, makeFactory } = require('./lib.js');
const g = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const tot = {}; let n = 0; const finalGold = [], waves = [];
const comp = {};
for (let sd = 1; sd <= 40; sd++) {
  const seed = sd * 7 + 3;
  const leaks = [];
