// statically drop steps that can never apply (they would be skipped at run time anyway)
(function prune() {
  const tier = new Array(16).fill(0), out = [];
  for (const s of g.steps) {
    if (s.k === 'b') { if (tier[s.s]) continue; tier[s.s] = 1; }
    else if (s.k === 'u') { if (!tier[s.s] || tier[s.s] >= 3) continue; tier[s.s]++; }
    else { if (!tier[s.s]) continue; tier[s.s] = 0; }
    out.push(s);
  }
  console.log('steps', g.steps.length, '->', out.length); g.steps = out;
})();
const OPS = { b: 0, u: 1, x: 2 };

