const fs = require('fs');
const { sim, makeFactory } = require('./lib.js');
const g = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const html = fs.readFileSync(process.argv[3], 'utf8');
const stratSrc = html.match(/<script id="rampart-strategy">\n([\s\S]*?)<\/script>/)[1];
const simSrc = html.match(/<script id="rampart-sim">\n([\s\S]*?)<\/script>/)[1];
const cs = new Function(stratSrc + ';return createStrategy;')();
const rs = new Function(simSrc + ';return rampartSimulate;')();
let bad = 0;
for (let sd = 1; sd <= 30; sd++) {
  const seed = sd * 31 + 5;
  const a = rs(cs, seed, 12020), b = sim(makeFactory(g.steps, { tm: g.tm, mf: g.mf }), seed, 12020);
  if (a.hash !== b.hash || a.score !== b.score) { bad++; console.log('MISMATCH', seed, a.score, b.score); }
}
console.log('mismatches', bad);
const t0 = Date.now(); const r = rs(cs, 42, 2020); console.log('seed42 2020 ticks', r.score, r.fallTick, r.hash, Date.now() - t0, 'ms');
const t1 = Date.now(); const r2 = rs(cs, 42, 12020); console.log('seed42 full', r2.score, r2.fallTick, Date.now() - t1, 'ms');
// determinism: two fresh strategies share no state
const x = rs(cs, 9, 12020), y = rs(cs, 9, 12020); console.log('deterministic', x.hash === y.hash);

